mapper.select:
SELECT rr.id, rr.rectify_notice_id, rr.ledger_code, rr.ent_id, ei.ent_name, rr.illegal_type_id, itd.type_name AS illegal_type_name, ild.level_name AS illegal_level_name, rr.evidence_url, rr.draft_time,
rr.review_status, su.user_name AS review_user_name, rr.review_time,
rr.rectify_deadline_time, rn.issue_time, rr.cancel_time, rr.cancel_reason_id, cancel.reason_name as cancel_reason, rn.receive_status, err.rectify_status,
lrl.ledger_code AS law_review_ledger_code,
rr.create_time, rr.update_time
FROM rectify_review rr
LEFT JOIN enterprise_info ei ON rr.ent_id = ei.id
left join cancel_reason_dict cancel on cancel.id = rr.cancel_reason_id
LEFT JOIN illegal_type_dict itd ON rr.illegal_type_id = itd.id
LEFT JOIN illegal_level_dict ild ON rr.illegal_level_id = ild.id
LEFT JOIN sys_user su ON rr.review_by = su.id
LEFT JOIN rectify_notice rn ON rn.rectify_review_id = rr.id
LEFT JOIN ent_rectify_record err ON err.rectify_notice_id = rn.id
LEFT JOIN law_review_ledger lrl ON lrl.rectify_review_id = rr.id
rr.deleted = b'0'
AND rr.id IN
#{id}
AND rr.ledger_code LIKE CONCAT('%', #{ledgerCode}, '%')
AND rr.ent_id = #{entId}
AND ei.ent_name LIKE CONCAT('%', #{entName}, '%')
AND rr.illegal_type_id = #{illegalTypeId}
AND itd.type_name = #{illegalTypeName}
AND rr.illegal_level_id = #{illegalLevelId}
AND ild.level_name = #{illegalLevelName}
AND rr.review_status = #{reviewStatus}
AND rr.review_by = #{reviewBy}
AND rr.draft_time >= #{draftTimeStart}
AND rr.draft_time <= #{draftTimeEnd}
AND rn.issue_time >= #{issueTimeStart}
AND rn.issue_time <= #{issueTimeEnd}
AND rr.cancel_time >= #{cancelTimeStart}
AND rr.cancel_time <= #{cancelTimeEnd}
ORDER BY rr.id DESC,rr.create_time
LIMIT #{pageSize} OFFSET #{offset}

