SELECT id, ledger_code, evidence_url
FROM rectify_review
WHERE id IN

    #{id}

ORDER BY ledger_code

LIMIT #{pageSize} OFFSET #{offset}

SELECT
COUNT(IF(rr.review_status = '待复审', 1, NULL)) AS pendingReviewCount,
COUNT(IF(rr.review_status = '已下发', 1, NULL)) AS issuedCount,
COUNT(IF(rr.review_status = '已撤销', 1, NULL)) AS canceledCount,
COUNT(IF(rr.review_status = '已完成', 1, NULL)) AS completedCount,
COUNT(*) AS totalCount,
--  新增：违规等级统计
COUNT(IF(ild.level_name = '一般', 1, NULL)) AS levelNormalCount,
COUNT(IF(ild.level_name = '较重', 1, NULL)) AS levelSeriousCount,
COUNT(IF(ild.level_name = '严重', 1, NULL)) AS levelVerySeriousCount
FROM rectify_review rr


LEFT JOIN enterprise_info ei ON rr.ent_id = ei.id
LEFT JOIN illegal_type_dict itd ON rr.illegal_type_id = itd.id
LEFT JOIN illegal_level_dict ild ON rr.illegal_level_id = ild.id
LEFT JOIN sys_user su ON rr.review_by = su.id
LEFT JOIN rectify_notice rn ON rn.rectify_review_id = rr.id
LEFT JOIN ent_rectify_record err ON err.rectify_notice_id = rn.id
LEFT JOIN law_review_ledger lrl ON lrl.rectify_review_id = rr.id



